calc.mjs.text:
// Pure pricing arithmetic for a maker selling 3D-printed parts (Etsy,
// Shopify, a craft fair table) rather than running a print farm at scale.
// No network, no state: every rate, gram, and hour is an input, so the
// result stays a transparent calculation the seller can check against their
// own filament spool and power bill instead of a rule of thumb like
// "3x the filament cost."
//
// Two costs are easy to leave out of that rule of thumb, and both are
// modeled here rather than assumed away:
//
//   1. Failed prints. A spaghetti print at hour six of an eight-hour job
//      still burned filament, electricity, and printer hours before it was
//      scrapped — and the successful reprint has to earn that back, not
//      just its own material. `failureRatePercent` inflates material,
//      electricity, and machine wear by how often an attempt fails, on the
//      logic that 1/(1 - failure rate) attempts are needed, on average, to
//      land one sellable part.
//   2. Marketplace fees are a percentage of the *selling price*, not the
//      cost — so they cannot simply be added as a flat cost line. Solving
//      for a price that leaves the target margin after the fee is taken
//      needs the fee and margin folded into the same denominator (mirrors
//      the fee-solved-into-price pattern in this portfolio's other
//      marketplace-fee calculators).

function number(value, name, { min = 0, allowZero = true } = {}) {
  const result = Number(value);
  if (!Number.isFinite(result)) throw new Error(`${name} must be a number`);
  if (result < min) throw new Error(`${name} must be at least ${min}`);
  if (!allowZero && result === 0) throw new Error(`${name} must be greater than zero`);
  return result;
}

export const DEFAULTS = {
  filamentUsedGrams: 45,
  filamentCostPerKg: 22,
  printTimeHours: 3,
  printerWattage: 120,
  electricityCostPerKwh: 0.16,
  printerCost: 250,
  printerLifetimeHours: 3000,
  failureRatePercent: 8,
  postProcessingMinutes: 10,
  laborRatePerHour: 20,
  packagingCost: 0.75,
  marketplaceFeePercent: 8.5,
  targetMarginPercent: 35,
  otherFixedCost: 0,
};

/**
 * Price one 3D-printed part.
 *
 * @param {object} input
 * @param {number} input.filamentUsedGrams     Filament consumed by one
 *   successful print, from the slicer's estimate.
 * @param {number} input.filamentCostPerKg     What you paid per kilogram
 *   of filament, including shipping.
 * @param {number} input.printTimeHours        Slicer-estimated print time
 *   for one successful attempt.
 * @param {number} input.printerWattage        Printer's power draw while
 *   printing, in watts (a spec-sheet figure or a plug-in meter reading).
 * @param {number} input.electricityCostPerKwh Your electricity rate.
 * @param {number} input.printerCost           What the printer cost you.
 * @param {number} input.printerLifetimeHours  Hours you expect the printer
 *   to run before it needs replacing — the depreciation horizon.
 * @param {number} input.failureRatePercent    Share of print attempts that
 *   fail and have to be redone (0-99). Inflates material, electricity, and
 *   machine-wear cost, since a failed attempt still spent all three before
 *   the eventual successful print did.
 * @param {number} input.postProcessingMinutes Manual time per sellable
 *   part: support removal, sanding, gluing, assembly.
 * @param {number} input.laborRatePerHour      What you value your own time
 *   at.
 * @param {number} input.packagingCost         Box, bag, or insert cost per
 *   unit shipped.
 * @param {number} input.marketplaceFeePercent Combined marketplace and
 *   payment-processing fee, as a percent of the selling price (0-99).
 * @param {number} input.targetMarginPercent   Desired net profit as a
 *   percent of the selling price, after the marketplace fee (0-99, and
 *   `targetMarginPercent + marketplaceFeePercent` must be below 100).
 * @param {number} input.otherFixedCost        Any other flat cost per part
 *   — a design-time amortization, a specialty additive.
 * @param {number|null} [input.actualSellingPrice] A price you are actually
 *   charging (or considering), to check its real profit and margin instead
 *   of the suggested price.
 */
export function calculatePrice(input) {
  const filamentUsedGrams = number(input.filamentUsedGrams, 'Filament used');
  const filamentCostPerKg = number(input.filamentCostPerKg, 'Filament cost per kg');
  const printTimeHours = number(input.printTimeHours, 'Print time', { allowZero: false });
  const printerWattage = number(input.printerWattage, 'Printer wattage');
  const electricityCostPerKwh = number(input.electricityCostPerKwh, 'Electricity cost');
  const printerCost = number(input.printerCost, 'Printer cost');
  const printerLifetimeHours = number(input.printerLifetimeHours, 'Printer lifetime hours', { allowZero: false });
  const failureRatePercent = number(input.failureRatePercent, 'Failure rate');
  if (failureRatePercent >= 100) throw new Error('Failure rate must be less than 100%');
  const postProcessingMinutes = number(input.postProcessingMinutes, 'Post-processing time');
  const laborRatePerHour = number(input.laborRatePerHour, 'Labor rate');
  const packagingCost = number(input.packagingCost, 'Packaging cost');
  const marketplaceFeePercent = number(input.marketplaceFeePercent, 'Marketplace fee');
  const targetMarginPercent = number(input.targetMarginPercent, 'Target margin');
  const otherFixedCost = number(input.otherFixedCost, 'Other fixed cost');
  if (marketplaceFeePercent + targetMarginPercent >= 100) {
    throw new Error('Marketplace fee and target margin together must be less than 100%');
  }

  const materialCost = (filamentUsedGrams / 1000) * filamentCostPerKg;
  const electricityCost = printTimeHours * (printerWattage / 1000) * electricityCostPerKwh;
  const depreciationCost = (printerCost / printerLifetimeHours) * printTimeHours;
  const perAttemptCost = materialCost + electricityCost + depreciationCost;

  // On average, 1/(1 - failure rate) attempts are needed to land one
  // sellable part, so the per-attempt cost (material, electricity, machine
  // wear only — not the one-time post-processing and packaging that only
  // ever touch the successful part) is inflated by that factor.
  const failureMultiplier = 1 / (1 - failureRatePercent / 100);
  const adjustedPerAttemptCost = perAttemptCost * failureMultiplier;
  const failureBufferCost = adjustedPerAttemptCost - perAttemptCost;

  const laborCost = (postProcessingMinutes / 60) * laborRatePerHour;
  const totalCost = adjustedPerAttemptCost + laborCost + packagingCost + otherFixedCost;

  // price*(1 - fee%) - totalCost = price*(margin%) solved for price.
  const suggestedPrice = totalCost / (1 - marketplaceFeePercent / 100 - targetMarginPercent / 100);
  const suggestedFeeAmount = suggestedPrice * (marketplaceFeePercent / 100);
  const suggestedProfit = suggestedPrice - suggestedFeeAmount - totalCost;
  const breakEvenPrice = totalCost / (1 - marketplaceFeePercent / 100);

  const hasActualPrice = input.actualSellingPrice !== null && input.actualSellingPrice !== undefined && input.actualSellingPrice !== '';
  let actual = null;
  if (hasActualPrice) {
    const actualSellingPrice = number(input.actualSellingPrice, 'Selling price', { allowZero: false });
    const actualFeeAmount = actualSellingPrice * (marketplaceFeePercent / 100);
    const actualNetRevenue = actualSellingPrice - actualFeeAmount;
    const actualProfit = actualNetRevenue - totalCost;
    actual = {
      feeAmount: actualFeeAmount,
      netRevenue: actualNetRevenue,
      profit: actualProfit,
      marginPct: actualSellingPrice > 0 ? (actualProfit / actualSellingPrice) * 100 : null,
      belowBreakEven: actualProfit < 0,
    };
  }

  return {
    materialCost,
    electricityCost,
    depreciationCost,
    perAttemptCost,
    failureMultiplier,
    failureBufferCost,
    adjustedPerAttemptCost,
    laborCost,
    packagingCost,
    otherFixedCost,
    totalCost,
    suggestedPrice,
    suggestedFeeAmount,
    suggestedProfit,
    breakEvenPrice,
    actual,
  };
}

gcode.mjs.text:
// Read the two numbers a seller otherwise retypes from the slicer -- grams of
// filament and print time -- out of the slicer's own G-code comments.
// Pure text parsing: no network, no state, and the file is never uploaded
// (the page reads it with FileReader in the browser).
//
// Formats recognised, each from the comment block the slicer writes itself:
//   PrusaSlicer / SuperSlicer / OrcaSlicer / Bambu Studio
//     ; filament used [g] = 12.3          ; total filament weight [g] : 12.3
//     ; estimated printing time (normal mode) = 1d 2h 3m 4s
//     ; total estimated time: 1h 2m 3s   (Bambu header)
//   Cura        ;TIME:11234 (seconds)     ;Filament used: 12.345m
//   Simplify3D  ;   Build time: 3 hours 12 minutes   ;   Plastic weight: 36.80 g
//
// Cura reports length, not weight, so grams are derived from length with the
// diameter and density the caller gives (defaults: 1.75 mm, PLA 1.24 g/cm3)
// and the result says so in `derived`. Multi-material files list one value per
// extruder separated by commas; they are summed.

function sumList(text) {
  const parts = text.split(/[,;]/).map((s) => Number(s.trim())).filter((n) => Number.isFinite(n));
  return parts.length ? parts.reduce((a, b) => a + b, 0) : null;
}

/** "1d 2h 3m 4s", "3h 12m", "45m 10s", "3 hours 12 minutes" -> seconds, or null. */
export function parseDuration(text) {
  const units = { d: 86400, h: 3600, m: 60, s: 1 };
  let total = 0;
  let found = false;
  for (const m of String(text).matchAll(/(\d+(?:\.\d+)?)\s*(days?|d|hours?|hrs?|h|minutes?|mins?|m|seconds?|secs?|s)\b/gi)) {
    total += Number(m[1]) * units[m[2][0].toLowerCase()];
    found = true;
  }
  return found ? total : null;
}

const line = (text, re) => {
  const m = re.exec(text);
  return m ? m[1].trim() : null;
};

export function parseGcode(text, { diameterMm = 1.75, densityGPerCm3 = 1.24 } = {}) {
  const src = String(text ?? "");
  let grams = null;
  let seconds = null;
  let lengthMm = null;
  let slicer = null;
  const derived = [];

  const g = line(src, /^;\s*(?:total )?filament (?:used \[g\]|weight \[g\])\s*[=:]\s*(.+)$/im);
  if (g !== null) { grams = sumList(g); slicer = "PrusaSlicer-family"; }

  const t = line(src, /^;\s*estimated printing time \(normal mode\)\s*=\s*(.+)$/im)
    ?? line(src, /^;\s*total estimated time:\s*(.+)$/im);
  if (t !== null) { seconds = parseDuration(t); slicer = slicer ?? "PrusaSlicer-family"; }

  const mm = line(src, /^;\s*filament used \[mm\]\s*=\s*(.+)$/im);
  if (mm !== null) lengthMm = sumList(mm);

  const cura = line(src, /^;TIME:\s*(\d+(?:\.\d+)?)\s*$/im);
  if (seconds === null && cura !== null) { seconds = Number(cura); slicer = "Cura"; }
  const curaLen = line(src, /^;Filament used:\s*(.+)$/im);
  if (curaLen !== null && lengthMm === null) {
    const metres = sumList(curaLen.replace(/m\b/gi, ""));
    if (metres !== null) { lengthMm = metres * 1000; slicer = slicer ?? "Cura"; }
  }

  const s3d = line(src, /^;\s*Plastic weight:\s*([\d.]+)\s*g/im);
  if (grams === null && s3d !== null) { grams = Number(s3d); slicer = "Simplify3D"; }
  const s3dTime = line(src, /^;\s*Build time:\s*(.+)$/im);
  if (seconds === null && s3dTime !== null) { seconds = parseDuration(s3dTime); slicer = slicer ?? "Simplify3D"; }
  const s3dLen = line(src, /^;\s*Filament length:\s*([\d.]+)\s*mm/im);
  if (lengthMm === null && s3dLen !== null) lengthMm = Number(s3dLen);

  if (grams === null && lengthMm !== null) {
    const area = Math.PI * (diameterMm / 2) ** 2; // mm^2
    grams = (lengthMm * area / 1000) * densityGPerCm3; // mm^3 -> cm^3 -> g
    derived.push(`grams computed from ${lengthMm.toFixed(0)} mm of ${diameterMm} mm filament at ${densityGPerCm3} g/cm³`);
  }

  const ok = grams !== null && seconds !== null;
  return {
    ok,
    slicer,
    grams: grams === null ? null : Math.round(grams * 100) / 100,
    hours: seconds === null ? null : Math.round((seconds / 3600) * 100) / 100,
    lengthMm,
    derived,
    missing: [grams === null ? "filament weight" : null, seconds === null ? "print time" : null].filter(Boolean),
  };
}

share.mjs.text:
// A maker pricing a print for a customer, a co-seller on the same Etsy shop,
// or their own other device has to retype fourteen numbers every time --
// filament grams, printer wattage, failure rate, and the rest -- because the
// only state this page kept was whatever was still in the tab. This module
// lets the whole pricing scenario travel: to the visitor's own browser
// between visits, and into a link they can send themselves or a co-seller.
//
// Nothing here is transmitted. `localStorage` is the visitor's own disk, and
// the link is only ever built in their browser and copied by them. The
// scenario travels in the URL *fragment* (`#...`), never the query string: a
// fragment is not sent in the request line a server logs, nor in a
// `Referer` header a later click would carry.
//
// The required field list is imported from `calc.mjs`'s `DEFAULTS` rather
// than restated here, so a field added to the arithmetic is shareable the
// moment it exists -- this portfolio has twice paid for a copied field list
// going stale instead of being derived (see CLAUDE.md, "168 became 169").
//
// `actualSellingPrice` is the one field that is not: it is only present once
// a maker has a real price to check, and `''` (nothing typed yet) is a
// materially different state from `0` (a giveaway). Leaving it out of the
// link the way the first version of this file did is the exact
// silent-divergence defect this portfolio has shipped before (a link that
// dropped `quantity` and `targetMargin`, so the recipient computed a
// different profit than the sender saw) -- here a co-seller who opens a
// shared link no longer sees the price the sender was checking, and the
// "check a price" panel goes quiet with nothing on screen to say why.
// `formValues` still clears any field a link does not carry, rather than
// leaving it unwritten: the same link could be opened on a page mid-edit or
// holding a saved draft, and leaving a stale value sitting in an unrelated
// field would silently mix the sender's price with a stranger's electricity
// rate.

import { DEFAULTS } from './calc.mjs';

/** Every field `calculatePrice` requires -- calc.mjs's own DEFAULTS keys. */
export const REQUIRED_FIELD_IDS = Object.freeze(Object.keys(DEFAULTS));

/** The one field the arithmetic treats as optional. See the header comment
 * above for why a link with nothing checked must leave this cleared, not
 * defaulted to 0 or left holding the recipient's own leftover figure. */
export const OPTIONAL_FIELD_IDS = Object.freeze(['actualSellingPrice']);

export const FIELD_IDS = Object.freeze([...REQUIRED_FIELD_IDS, ...OPTIONAL_FIELD_IDS]);

function usableNumber(value) {
  if (value === '' || value === null || value === undefined) return null;
  if (String(value).trim() === '') return null;
  const result = Number(value);
  return Number.isFinite(result) && result >= 0 ? result : null;
}

export function encodeInputs(input) {
  const params = new URLSearchParams();
  for (const id of FIELD_IDS) {
    const value = usableNumber(input?.[id]);
    if (value !== null) params.set(id, String(value));
  }
  return params.toString();
}

export function decodeInputs(source) {
  const params = new URLSearchParams(String(source || '').replace(/^[?#]/, ''));
  const result = {};
  for (const id of FIELD_IDS) {
    if (!params.has(id)) continue;
    const value = usableNumber(params.get(id));
    if (value !== null) result[id] = value;
  }
  return result;
}

/**
 * Every field the form owns, as the string a form control holds -- the
 * shared value where the link had one, and `''` where it did not.
 */
export function formValues(decoded) {
  const source = decoded || {};
  return Object.fromEntries(FIELD_IDS.map((id) => [id, id in source ? String(source[id]) : '']));
}

usage.mjs.text:
const KEY = '3d-print-price-calculator-usage';
const OPT_OUT = '3d-print-price-calculator-usage-opt-out';

function storage() {
  try {
    return typeof localStorage !== 'undefined' ? localStorage : null;
  } catch {
    return null;
  }
}

export function usageAllowed() {
  if (typeof navigator !== 'undefined' && (navigator.doNotTrack === '1' || navigator.globalPrivacyControl)) {
    return false;
  }
  const ls = storage();
  if (!ls) return false;
  return ls.getItem(OPT_OUT) !== 'true';
}

export function recordEvent(event = 'price-calculated') {
  if (!usageAllowed()) return;
  try {
    const ls = storage();
    if (!ls) return;
    const counts = JSON.parse(ls.getItem(KEY) || '{}');
    counts[event] = (counts[event] || 0) + 1;
    ls.setItem(KEY, JSON.stringify(counts));
  } catch { /* Private browsing must not break the calculator. */ }
}

export function toggleUsage(enabled) {
  try {
    const ls = storage();
    if (!ls) return;
    ls.setItem(OPT_OUT, enabled ? 'false' : 'true');
  } catch { /* optional measurement */ }
}
